-- Read-only reconciliation query: execute with a SELECT-only database role.
-- Replace the UUID with a submission generated by this test run.
-- Checks exactly one executor job, terminal status, at least one result row,
-- and whether any result row is duplicated for this submission.

WITH target AS (
    SELECT '00000000-0000-4000-8000-000000000000'::uuid AS submission_id
),
submission AS (
    SELECT s.id, s.assignment_id, s.student_id, s.status, s.created_at, s.updated_at
    FROM submissions s JOIN target t ON s.id = t.submission_id
    WHERE s.deleted_at IS NULL
),
jobs AS (
    SELECT j.id, j.submission_id, j.status, j.retry_count, j.started_at,
           j.completed_at, j.created_at, j.updated_at
    FROM grading_jobs j JOIN target t ON j.submission_id = t.submission_id
    WHERE j.deleted_at IS NULL
),
results AS (
    SELECT r.id, r.submission_id, r.status, r.score, r.scope, r.is_latest,
           r.started_at, r.completed_at, r.created_at
    FROM results r JOIN target t ON r.submission_id = t.submission_id
    WHERE r.deleted_at IS NULL
)
SELECT
    (SELECT count(*) FROM submission) AS submission_rows,
    (SELECT count(*) FROM jobs) AS grading_job_rows,
    (SELECT count(*) FROM results) AS result_rows,
    (SELECT jsonb_agg(to_jsonb(submission)) FROM submission) AS submission,
    (SELECT jsonb_agg(to_jsonb(jobs)) FROM jobs) AS grading_jobs,
    (SELECT jsonb_agg(to_jsonb(results)) FROM results) AS results,
    CASE
        WHEN (SELECT count(*) FROM submission) <> 1 THEN 'CHECK_SUBMISSION_ROW'
        WHEN (SELECT count(*) FROM jobs) <> 1 THEN 'CHECK_JOB_IDEMPOTENCY'
        WHEN (SELECT count(*) FROM results) = 0 THEN 'CHECK_RESULT_WRITE'
        WHEN (SELECT count(*) FROM submission WHERE status IN ('DONE', 'FAILED')) = 1
             AND (SELECT count(*) FROM results WHERE status IN ('DONE', 'FAILED')) = 0
            THEN 'CHECK_TERMINAL_STATUS_MISMATCH'
        ELSE 'RECONCILED'
    END AS reconciliation;
